// Normalize Vapi/Retell payload into a canonical shape
// Vapi end-of-call-report: $json.message.call.customer.number + transcript
// Retell call_ended:        $json.call.from_number + transcript
// Adjust the two extractors below to match YOUR provider.

const body = $input.first().json;

// --- Vapi shape (default) ---
let callerPhone = body?.message?.call?.customer?.number;
let transcript = body?.message?.transcript ?? body?.message?.artifact?.transcript;
let callId = body?.message?.call?.id;

// --- Retell fallback ---
if (!callerPhone) callerPhone = body?.call?.from_number;
if (!transcript) transcript = body?.call?.transcript;
if (!callId) callId = body?.call?.call_id;

if (!callerPhone) {
  // Unknown caller (no phone in payload). Still let the agent answer, but
  // skip the memory lookup. The downstream IF branches on this flag.
  return [{ json: { callerPhone: null, transcript, callId, hasPhone: false } }];
}

// E.164-ish normalization: strip spaces, parens, dashes; keep leading +
const normalized = String(callerPhone).replace(/[\s\(\)\-]/g, '');

return [{
  json: {
    callerPhone: normalized,
    transcript: transcript ?? '',
    callId: callId ?? '',
    hasPhone: true,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a plain-text context block the LLM can read.
// Both phone-known and anonymous (no phone) paths converge here.

const transcript = $('Normalize Payload').item.json.transcript || '(no transcript)';
const callerPhone = $('Normalize Payload').item.json.callerPhone || 'anonymous';
const hasPhone = $('Normalize Payload').item.json.hasPhone === true;

// Pull recent memory results if the caller was known (phone path only)
let contextLines = [];
if (hasPhone) {
  try {
    const memSearch = $('Memory: Recent Context').first()?.json;
    const results = memSearch?.results ?? memSearch?.data?.results ?? [];
    contextLines = results.slice(0, 5).map((r, i) => {
      const text = r.content ?? r.text ?? r.formatted ?? JSON.stringify(r).slice(0, 200);
      return `${i + 1}. ${text}`;
    });
  } catch (e) {
    // First-time caller path, no prior memory to summarize
    contextLines = ['(this is a new caller, no prior interactions on file)'];
  }
} else {
  // Anonymous caller path: no memory lookup ran, no prior context to surface
  contextLines = ['(caller is anonymous, no memory lookup performed)'];
}

const contextBlock = contextLines.length
  ? contextLines.join('\n')
  : '(no relevant prior context)';

const systemPrompt = hasPhone
  ? `You are a friendly voice agent for a small business.\n\nCaller phone: ${callerPhone}\n\nWhat we know about this caller from prior calls:\n${contextBlock}\n\nReply concisely (under 60 words) and reference past context when relevant.`
  : `You are a friendly voice agent for a small business.\n\nThe caller is anonymous (no phone number was provided by the voice provider). Treat this as a first-time caller. If the conversation needs continuity, ask the caller to share an email or callback number so you can recognize them next time.\n\nReply concisely (under 60 words).`;

return [{
  json: {
    callerPhone,
    transcript,
    contextBlock,
    hasPhone,
    systemPrompt,
  },
}];

// Normalize the LLM output across providers into a single field `replyText`.
// OpenAI:    $json.choices[0].message.content
// Anthropic: $json.content[0].text
// Fallback:  any string-shaped property we can find.

const raw = $input.first().json;

let replyText = '';

// OpenAI shape
if (raw?.choices?.[0]?.message?.content) {
  replyText = raw.choices[0].message.content;
}
// Anthropic shape
else if (Array.isArray(raw?.content) && raw.content[0]?.text) {
  replyText = raw.content[0].text;
}
// Some n8n-wrapped variants
else if (raw?.message?.content) {
  replyText = raw.message.content;
}
else if (raw?.text) {
  replyText = raw.text;
}
else if (raw?.reply) {
  replyText = raw.reply;
}
else {
  replyText = '(LLM returned no text, check provider response shape)';
}

return [{
  json: {
    replyText: String(replyText).trim(),
    provider: $('Set Provider').item.json.provider,
  },
}];

// Webhook HMAC verification (opt-in via VAPI_SIGNING_SECRET or RETELL_SIGNING_SECRET).
// Vapi sends 'x-vapi-signature' header with HMAC-SHA256 of raw body, hex-encoded.
// Retell sends 'x-retell-signature' (same shape).
//
// The Webhook node has rawBody: true so the byte-stream is preserved on
// $json.rawBody as a string. We MUST compute HMAC against the raw bytes
// the provider signed, NOT against a re-stringified JSON object (which
// has different byte-order and whitespace).
//
// To enable: set VAPI_SIGNING_SECRET (or RETELL_SIGNING_SECRET) env var on
// the n8n host AND configure the same secret in your voice provider dashboard.
// To disable: leave both env vars unset (default). The node passes through.
//
// Length-guard before timingSafeEqual is mandatory. Without it, an attacker
// can trigger a RangeError with a 1-char signature and crash the workflow.

const vapiSecret = $env.VAPI_SIGNING_SECRET;
const retellSecret = $env.RETELL_SIGNING_SECRET;

if (!vapiSecret && !retellSecret) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const headers = item?.headers ?? {};

// n8n Webhook v2 with rawBody: true populates $json.rawBody as a string.
// Fallback chain: rawBody field > body if it is already a string > stringify.
// The stringify fallback only runs if the Webhook node was misconfigured
// (rawBody: false), in which case HMAC will fail loud and the user will
// fix the config.
const rawBody = item?.rawBody
  ?? (typeof item?.body === 'string' ? item.body : JSON.stringify(item?.body ?? {}));

const crypto = require('crypto');

function verifyHmac(secret, headerName) {
  const sig = headers[headerName];
  if (!sig || typeof sig !== 'string') return false;
  const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  const sigBuf = Buffer.from(sig, 'hex');
  const expBuf = Buffer.from(expected, 'hex');
  if (sigBuf.length !== expBuf.length) return false;
  return crypto.timingSafeEqual(sigBuf, expBuf);
}

let verified = false;
if (vapiSecret && verifyHmac(vapiSecret, 'x-vapi-signature')) verified = true;
if (!verified && retellSecret && verifyHmac(retellSecret, 'x-retell-signature')) verified = true;

if (!verified) {
  throw new Error('Webhook HMAC verification failed: signature missing or mismatch (check rawBody is enabled on the Webhook node)');
}

return [{ json: $input.first().json }];

// Rate limit (opt-in via RATE_LIMIT_ENABLED=1).
// Per-caller-phone (or per-IP if anonymous) 60 requests in a 5-min window.
// For voice this matters less than for chat (callers don't burst-call), but
// a leaked webhook URL can spike LLM cost so we keep this layer for parity.
//
// To enable: set the n8n env var RATE_LIMIT_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic. For real production
// loads use Nginx limit_req_zone or Cloudflare WAF in front of n8n.

const enabled = $env.RATE_LIMIT_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const body = item?.body ?? item;
const callerPhone = body?.message?.call?.customer?.number ?? body?.call?.from_number;
const ip = item?.headers?.['x-forwarded-for']?.split(',')[0]?.trim() ?? item?.headers?.['x-real-ip'] ?? 'unknown';
const bucketKey = callerPhone ? `phone:${callerPhone}` : `ip:${ip}`;

const data = $getWorkflowStaticData('global');
const buckets = data.rateBuckets ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const LIMIT = 60;
const MAX_BUCKETS = 5000;

const bucket = buckets[bucketKey] ?? { count: 0, windowStart: now };
if (now - bucket.windowStart > WINDOW_MS) {
  bucket.count = 0;
  bucket.windowStart = now;
}
bucket.count++;
buckets[bucketKey] = bucket;

if (Object.keys(buckets).length > MAX_BUCKETS) {
  const cutoff = now - WINDOW_MS;
  for (const k of Object.keys(buckets)) {
    if (buckets[k].windowStart < cutoff) delete buckets[k];
  }
}
data.rateBuckets = buckets;

if (bucket.count > LIMIT) {
  throw new Error(`Rate limit exceeded for ${bucketKey}: ${bucket.count} requests in 5 min window`);
}

return [{ json: item }];

// Idempotency check (opt-in via IDEMPOTENCY_ENABLED=1).
// Vapi/Retell can re-deliver end-of-call-report on transient 5xx. Without
// dedup the workflow fires twice per call and writes duplicate observations.
// Idempotency key is the callId (Vapi message.call.id / Retell call.call_id).
//
// To enable: set the n8n env var IDEMPOTENCY_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic and not cluster-
// aware. For production scale, swap the staticData block for Redis SET NX
// EX 300 (atomic, cluster-aware, auto-expires).

const enabled = $env.IDEMPOTENCY_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const body = item?.body ?? item;
const callId = body?.message?.call?.id ?? body?.call?.call_id;
const idempotencyKey = callId ? `voice:${callId}` : null;

if (!idempotencyKey) {
  // No callId available, pass through (better than dropping)
  return [{ json: item }];
}

const data = $getWorkflowStaticData('global');
const seen = data.seenKeys ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}

if (seen[idempotencyKey]) {
  return [];
}
seen[idempotencyKey] = now;
data.seenKeys = seen;

return [{ json: item }];

// LLM Fallback Reply: fires when OpenAI/Anthropic Reply errors,
// or when Route by Provider receives an unknown provider value.
// Builds a graceful voice-friendly reply and an error-learn payload.
//
// Two arrival paths land here:
//   1. LLM error (provider returned non-2xx) ,  input has $json.error
//   2. Router fallback (Route by Provider had no matching rule) ,  input has
//      the original prompt object (systemPrompt, transcript, callerPhone, etc.)
//      WITHOUT an error field. We must NOT JSON.stringify the whole input
//      because systemPrompt contains private memory context.

const errorRaw = $input.first().json;
const provider = $('Set Provider').item.json.provider ?? 'unknown';

const isLlmError = !!(errorRaw?.error || errorRaw?.message);
let errorMessage;
if (isLlmError) {
  errorMessage = errorRaw?.error?.message
    ?? errorRaw?.error?.name
    ?? errorRaw?.message
    ?? 'Unknown LLM error';
} else {
  errorMessage = `Unknown provider value: ${provider}. Set "provider" to "openai" or "anthropic" in the Set Provider node.`;
}

const callerPhone = $('Normalize Payload').item.json.callerPhone ?? 'anonymous';
const hasPhone = $('Normalize Payload').item.json.hasPhone === true;
const callId = $('Normalize Payload').item.json.callId ?? '';

// Voice fallback should be SHORT. The voice provider TTS reads it aloud.
const fallbackText = "Sorry, I'm having trouble right now. Please try calling back in a minute.";

return [{
  json: {
    replyText: fallbackText,
    provider,
    isFallback: true,
    isRouterFallback: !isLlmError,
    errorMessage: String(errorMessage),
    callerPhone,
    hasPhone,
    callId,
  },
}];
